34	// Read side — "prefer Y, fall back to X": the ordered list of acceptable paths
35	// for a canonical target (canonical first, then its legacy aliases). A tolerance
36	// point consults this instead of hardcoding its own LEGACY_* constant, so a
37	// rename is declared once here and every reader picks it up. Unknown targets
38	// resolve to just themselves.
39	export function resolvePath(migrations, canonical) {
40	  for (const m of migrations) {
41	    for (const a of m.aliases ?? []) {
42	      if (a.canonical === canonical) return [a.canonical, ...(a.legacy ?? [])];
43	    }
44	  }
45	  return [canonical];
46	}
47	
48	// Write side — "and rename X -> Y": for each alias whose legacy path still
49	// exists and whose canonical does not, move legacy -> canonical. `exists` and
50	// `move` are injected so the same logic drives a local checkout (sync fs) or a
51	// future API applier (async). Idempotent — a no-op once the rename is done.
52	export async function applyFileAliases(migration, { exists, move }) {
53	  const moved = [];
54	  for (const a of migration.aliases ?? []) {
55	    for (const legacy of a.legacy ?? []) {
56	      if ((await exists(legacy)) && !(await exists(a.canonical))) {
57	        await move(legacy, a.canonical);
58	        moved.push(`${legacy} -> ${a.canonical}`);
59	      }
60	    }
61	  }
62	  return moved;
63	}
