65	// Write side — "vendor these pack templates into the repo": for each declared
66	// materialization {template, dest}, copy the canon template to its destination
67	// when the dest is missing or has drifted from the template (idempotent; a
68	// hand-edited copy self-heals on the next pass). `readTemplate` reads from the
69	// canon (the pack tree / mounted .claudinite), `read`/`write` act on the consumer
70	// repo — the source and destination roots differ in a consumer, so they are
71	// distinct injected readers. Gated by the migration's `appliesTo` so it only
72	// touches repos that ship the pipeline (never the canon repo itself).
73	// A materialization whose dest is a WORKFLOW FILE can only be written by a caller that
74	// can get it delivered. The nightly converge pushes with the Action's GITHUB_TOKEN, which
75	// GitHub never lets write under `.github/workflows/`, and the refusal rejects the whole
76	// ref — so writing one into a tree that is about to be pushed by such a caller does not
77	// deliver a workflow, it fails the entire converge and everything else riding it.
78	//
79	// The capable caller announces itself with this variable. The baselining worker sets it
80	// when it can WITHHOLD those paths from its commit and hand them to the agent stage;
81	// anything else — an older vendored worker, a hand-run `node migrations/apply.mjs`, CI —
82	// leaves it unset and the workflow materialization is skipped with a note.
83	//
84	// An ENV HANDSHAKE rather than a probe of the repo on disk, because what matters is what
85	// the RUNNING process can do and the disk cannot answer that: the vendor step earlier in
86	// the same cycle replaces the on-disk worker with the new one while the old code is still
87	// executing.
88	export const WITHHOLD_CAPABLE_ENV = 'CLAUDINITE_CAN_WITHHOLD_WORKFLOWS';
89	const WORKFLOW_DEST = '.github/workflows/';
90	export const callerCanDeliverWorkflows = (env = process.env) => env[WITHHOLD_CAPABLE_ENV] === '1';
91	
92	export async function applyMaterializations(migration, { readTemplate, read, write, env = process.env }) {
93	  if (!migration.materialize?.length) return [];
94	  if (migration.appliesTo && !(await migration.appliesTo(read))) return [];
95	  const done = [];
96	  for (const { template, dest } of migration.materialize) {
97	    const content = await readTemplate(template);
98	    if (content == null) continue; // template missing (partial mount) — skip, never clobber with nothing
99	    if ((await read(dest)) === content) continue; // already vendored, unchanged
100	    if (dest.startsWith(WORKFLOW_DEST) && !callerCanDeliverWorkflows(env)) {
101	      // Reported rather than silent — a silent skip reads as "already current". A caller
102	      // that can withhold writes it on a later cycle.
103	      done.push(`SKIPPED ${dest} (workflow file; this caller cannot deliver one)`);
104	      continue;
105	    }
106	    await write(dest, content);
107	    done.push(`${dest} <- ${template}`);
108	  }
109	  return done;
110	}
111	
112	// Write side — "rewrite these refs in place": for each declared file, apply its
113	// literal from->to replacements (only those whose `from` is still present),
114	// writing back when anything changed. Idempotent — a no-op once every `from` is
115	// gone. Preserves the rest of the file, so per-repo tweaks the template can't
116	// carry (e.g. an uncommented build_env block) survive. Same `appliesTo` gate.
117	export async function applyRewrites(migration, { read, write }) {
118	  if (!migration.rewrite?.length) return [];
119	  if (migration.appliesTo && !(await migration.appliesTo(read))) return [];
120	  const done = [];
121	  for (const { file, replace } of migration.rewrite) {
122	    const text = await read(file);
123	    if (text == null) continue;
124	    let next = text;
125	    for (const { from, to } of replace ?? []) next = next.split(from).join(to);
126	    if (next !== text) { await write(file, next); done.push(file); }
127	  }
128	  return done;
129	}
130	
131	// The declaration a pack-seeding op writes into. Fixed, not a parameter: this op
132	// declares PACKS, and a repo's declaration lives in exactly one file. A `file` knob
133	// would quietly make it a general JSON editor, which is a much larger thing to own.
134	export const DECLARATION = '.claudinite-checks.json';
135	
136	// Write side — "every member should now declare this pack": for each declared
137	// `{ id, config }`, add that pack to the member's `packs` when it is absent, and
138	// fill in a `config` the entry does not already carry. The op the other three could
139	// not express — `materialize` writes a whole template (it would clobber a per-repo
140	// declaration) and `rewrite` replaces literal text (declarations share no literal
141	// across repos) — and the shape a fleet-wide capability change actually has: a pack
142	// every member should run, whose parameters the canon knows and the member cannot
143	// derive.
144	//
145	// SEEDING, NEVER OVERRIDING. A pack the repo already declares keeps its entry, and a
146	// config it already carries is left exactly as it is: both are that repo's decisions,
147	// and a migration that reasserted them would fight the project every night. That
148	// makes the op idempotent by construction — a no-op once the entry is there.
149	//
150	// ORDER MATTERS AROUND IT. Declaring a pack whose code is not in the member's mount
151	// is a blocking `config` error there, so the caller must re-converge the mount after
152	// applying (baselining does; see its worker). This module only writes the file.
153	//
154	// It round-trips the file through JSON rather than editing settings as text, so the
155	// result is canonical 2-space settings with a trailing newline (what `--init` writes,
156	// and what every fleet declaration already is). Malformed JSON is left alone: the
157	// world runner reports it as the settings error it is, and a migration is not the
158	// place to guess at a repair. Same `appliesTo` gate as the other write ops.
159	export async function applyPackDeclarations(migration, { read, write }) {
160	  if (!migration.declarePacks?.length) return [];
161	  if (migration.appliesTo && !(await migration.appliesTo(read))) return [];
162	  const raw = await read(DECLARATION);
163	  if (raw == null) return [];                       // not a member — nothing to declare into
164	  let config;
165	  try { config = JSON.parse(raw); } catch { return []; }
166	  if (config === null || typeof config !== 'object' || Array.isArray(config)) return [];
167	  const packs = Array.isArray(config.packs) ? [...config.packs] : [];
168	  const idOf = (e) => (typeof e === 'string' ? e : e?.id);
169	  const done = [];
170	  for (const { id, config: packConfig } of migration.declarePacks) {
171	    const at = packs.findIndex((e) => idOf(e) === id);
172	    if (at === -1) {
173	      packs.push(packConfig ? { id, config: packConfig } : id);
174	      done.push(`${DECLARATION}: declared ${id}`);
175	      continue;
176	    }
177	    // Declared already: the only thing still owed is a config it never got.
178	    if (!packConfig) continue;
179	    const prior = typeof packs[at] === 'string' ? { id } : packs[at];
180	    if (prior.config) continue;                     // the repo's own parameters — untouched
181	    packs[at] = { ...prior, id, config: packConfig };
182	    done.push(`${DECLARATION}: configured ${id}`);
183	  }
184	  if (done.length) await write(DECLARATION, `${JSON.stringify({ ...config, packs }, null, 2)}\n`);
185	  return done;
186	}
