36	// The pack-badge row: the marks of the packs this repo declares, on a single
37	// line of its README. Adoption seeds it and the repo owns it from there — which
38	// is why the row is gated behind `{ badges: true }` (the CLI's `--badges`, passed
39	// by bootstrap alone) rather than converged like the surfaces around it. A
40	// README belongs to its repo: a nightly that re-derived this row would rewrite a
41	// member's README every time its declaration moved, so the nightly stays out and
42	// a stale row is the repo's to fix (re-run the converge with `--badges`).
43	//
44	// Delimited by HTML comments rather than located by position, so the row can be
45	// re-converged in place wherever the repo has moved it, and so anything the repo
46	// writes AFTER the closing marker on the same line (a tagline, a build badge) is
47	// its own and survives untouched — which is why the CLOSING marker stays inline,
48	// at the end of the badges' own line.
49	//
50	// The OPENING marker gets a line to itself, and that newline is load-bearing: a
51	// line that BEGINS with `<!--` opens a CommonMark HTML block, and every character
52	// through the line carrying `-->` is then emitted as raw HTML. Put the badges
53	// after the opening marker on one line and a README renders the literal text
54	// `![basics](…)` instead of the images (#587). Breaking the line ends the HTML
55	// block at the marker, so the badges start a paragraph and parse as markdown.
56	export const BADGE_ROW_START = '<!-- claudinite:packs -->';
57	export const BADGE_ROW_END = '<!-- /claudinite:packs -->';
58	const BADGE_ROW_RE = new RegExp(`${BADGE_ROW_START}[\\s\\S]*?${BADGE_ROW_END}`);
