61	// The whole line (and its trailing newline) is removed wherever it appears.
62	const CORPUS_IMPORT_RE = /^.*@\.claudinite\/shared\/CLAUDE\.md.*\n?/m;
63	
64	// The project's settings, loaded through the one reader that validates them.
65	// Dynamic and in one place: the scheduler reaches the checks helpers exactly here,
66	// so the cross-tree import stays a single, reviewable edge.
67	const repoConfig = async (root) => (await import('../checks/helpers/repo-context.mjs')).loadConfig(root);
68	
69	// The repo Actions secrets its scheduled tasks declare via `required_secrets`,
70	// deduped and sorted. Async because task discovery is; pure otherwise.
71	export async function declaredSecrets(root, config) {
72	  const { discoverTasks } = await import('./discover.mjs');
73	  const { tasks } = await discoverTasks(root, config);
74	  return [...new Set(tasks.flatMap((t) => t.decl?.required_secrets ?? []))].sort();
75	}
76	
77	// Stamp the declared secrets into the scheduler workflow's engine step, beside
78	// GITHUB_TOKEN. This is the whole delivery mechanism: GitHub Actions requires each
79	// secret to be named statically in the workflow, and a task's `required_secrets` is
80	// exactly that list — so the wiring converge writes it, and a worker then reads
81	// `process.env.<NAME>` like any other environment variable. No bundle, no parsing,
82	// no engine-side selection. Regenerated from the stub each converge, so the list
83	// tracks the declarations rather than accumulating.
84	export function withDeclaredSecrets(stubText, names = []) {
85	  if (!names.length) return stubText;
86	  const lines = names.map((n) => `          ${n}: \${{ secrets.${n} }}`).join('\n');
87	  return stubText.replace(/^(\s*GITHUB_TOKEN: \$\{\{ github\.token \}\})$/m, `$1\n${lines}`);
88	}
89	
90	// Re-converge the scheduler workflow to the vendored stub, with the cron minute set
91	// to this repo's stable hashed value (never guessed — hash-minute.mjs, a pure
92	// function of the full name, so re-vendors and this convergence agree) and the
93	// declared `required_secrets` stamped into the engine step's env. `stubText` is the
94	// vendored stub's content (the caller reads it from the mount). Returns true when
95	// the file was written (absent, or drifted from the target).
96	export function convergeSchedulerWorkflow(root, fullName, stubText, secretNames = []) {
97	  const target = withDeclaredSecrets(stubText, secretNames)
98	    .replace(/cron:\s*'[^']*'/, `cron: '${hashedCron(fullName)}'`);
99	  const path = join(root, SCHEDULER_WORKFLOW);
100	  const current = existsSync(path) ? readFileSync(path, 'utf8') : null;
101	  if (current === target) return false;
102	  mkdirSync(dirname(path), { recursive: true });
103	  writeFileSync(path, target);
104	  return true;
105	}
106	
107	// Ensure the required settings hooks are present (add-if-missing, never clobber).
108	// Returns { added: [labels], error? }. A malformed settings file is reported, never
109	// overwritten (the transactional stance — surface it, don't destroy hand config).
110	export function ensureHooks(root) {
111	  const path = join(root, SETTINGS_PATH);
112	  let settings = {};
113	  if (existsSync(path)) {
114	    try { settings = JSON.parse(readFileSync(path, 'utf8')); }
115	    catch { return { added: [], error: `${SETTINGS_PATH} is not valid JSON — left untouched` }; }
116	  }
117	  settings.hooks ??= {};
118	  const added = [];
119	  for (const h of REQUIRED_HOOKS) {
120	    const list = (settings.hooks[h.event] ??= []);
121	    const present = list.some((group) =>
122	      (h.matcher == null || group.matcher === h.matcher)
123	      && (group.hooks ?? []).some((entry) => entry?.command === h.command));
124	    if (!present) {
125	      list.push({ ...(h.matcher != null ? { matcher: h.matcher } : {}), hooks: [{ type: 'command', command: h.command }] });
126	      added.push(`${h.event}${h.matcher ? `[${h.matcher}]` : ''}`);
127	    }
128	  }
129	  if (added.length) {
130	    mkdirSync(dirname(path), { recursive: true });
131	    writeFileSync(path, JSON.stringify(settings, null, 2) + '\n');
132	  }
133	  return { added };
134	}
135	
136	// Remove the retired `@.claudinite/shared/CLAUDE.md` corpus-index import (#385) from
137	// the repo's CLAUDE.md. Returns true when a line was removed.
138	export function removeRetiredCorpusImport(root) {
139	  const path = join(root, CLAUDE_MD);
140	  if (!existsSync(path)) return false;
141	  const text = readFileSync(path, 'utf8');
142	  if (!CORPUS_IMPORT_RE.test(text)) return false;
143	  writeFileSync(path, text.replace(CORPUS_IMPORT_RE, ''));
144	  return true;
145	}
146	
147	// Strip the retired `badges` setting from `.claudinite-checks.json`. `badges` is
148	// not in CONFIG_KEYS, so a member still carrying it gets an unknown-setting error
149	// until the key goes; doing it here — beside the retired corpus import, for the
150	// same reason — means the converge that already runs on every member clears it,
151	// and nobody hand-edits a settings file to satisfy a check.
152	// Returns true when the key was removed. A malformed settings file is left alone.
153	//
154	// Cut out as TEXT, re-serializing only as a fallback: a JSON round-trip rewrites
155	// the whole file — re-escaping every non-ASCII character in the prose a settings
156	// file is full of — so a three-line deletion arrives as a diff touching every
157	// `reason` in the repo.
158	export function removeRetiredBadgeSetting(root) {
159	  const path = join(root, '.claudinite-checks.json');
160	  if (!existsSync(path)) return false;
161	  const text = readFileSync(path, 'utf8');
162	  let raw;
163	  try { raw = JSON.parse(text); } catch { return false; }
164	  if (raw === null || typeof raw !== 'object' || Array.isArray(raw) || raw.badges === undefined) return false;
165	  // The key as a materialized settings file carries it: two-space indent, either
166	  // followed by a comma (mid-object) or preceded by one (last key).
167	  const surgical = text.replace(/(,)?\n[ \t]*"badges"[ \t]*:[ \t]*\{[^{}]*\}(,)?(?=\n)/, (m, before, after) => (before && after ? ',' : ''));
168	  const next = surgical !== text && parses(surgical, raw) ? surgical
169	    : JSON.stringify(rest(raw), null, 2) + '\n';
170	  writeFileSync(path, next);
171	  return true;
172	}
173	
174	const rest = ({ badges, ...keep }) => keep;
175	// The surgical cut is only taken when it produces the settings the round-trip would
176	// have — never trust a regex against JSON without re-reading what it made.
177	const parses = (text, raw) => {
178	  try { return JSON.stringify(JSON.parse(text)) === JSON.stringify(rest(raw)); }
179	  catch { return false; }
180	};
181	
182	// The row's entries: each declared pack (the `requires` closure included, in
183	// declaration order) that has a badge on disk, as { id, path } with the path
184	// relative to the repo root. Derived from the pack's own `dir`, so it resolves to
185	// `packs/<id>/…` in the canon home and `.claudinite/shared/packs/<id>/…` in a
186	// consumer with no branch on which repo this is. A pack whose badge is missing is
187	// skipped rather than reported: a repo's own local pack need not have one.
188	export async function badgeRowEntries(root, config) {
189	  const { loadPacks, resolveDeclaredPacks, packEntryId } = await import('../pack_loader/pack-registry.mjs');
190	  const packs = await loadPacks({ localRoot: root });
191	  const byId = new Map(packs.map((p) => [p.id, p]));
192	  const entries = [];
193	  for (const entry of resolveDeclaredPacks(config.packs ?? [], packs)) {
194	    const pack = byId.get(packEntryId(entry));
195	    if (!pack || typeof pack.badge !== 'string' || !pack.badge) continue;
196	    const path = relative(root, join(pack.dir, pack.badge)).split('\\').join('/');
197	    if (existsSync(join(root, path))) entries.push({ id: pack.id, path });
198	  }
199	  return entries;
200	}
201	
202	export const renderBadgeRow = (entries) =>
203	  `${BADGE_ROW_START}\n${entries.map((e) => `![${e.id}](${e.path} "${e.id}")`).join(' ')}${BADGE_ROW_END}`;
204	
205	// Write the row into the repo's README: replacing the delimited block where one
206	// exists, otherwise introducing it just under the title (a README's badges belong
207	// where a reader looks first) or at the very top when there is no heading.
208	// Returns true when the file was written. No README, or nothing to show, means
209	// nothing to do — this converge never creates a README.
210	export function convergeBadgeRow(root, entries) {
211	  const path = join(root, README);
212	  if (!existsSync(path) || !entries.length) return false;
213	  const text = readFileSync(path, 'utf8');
214	  const row = renderBadgeRow(entries);
215	  if (BADGE_ROW_RE.test(text)) {
216	    const next = text.replace(BADGE_ROW_RE, row);
217	    if (next === text) return false;
218	    writeFileSync(path, next);
219	    return true;
220	  }
221	  const lines = text.split('\n');
222	  const title = lines.findIndex((l) => l.startsWith('# '));
223	  const at = title === -1 ? 0 : title + 1;
224	  lines.splice(at, 0, ...(at === 0 ? [row, ''] : ['', row]));
225	  writeFileSync(path, lines.join('\n'));
226	  return true;
227	}
228	
229	// Converge every wiring surface, returning a flat summary of what changed (empty
230	// when the repo was already converged). `stubText` is the vendored scheduler stub.
231	//
232	// `badges` defaults off, and that default is the point: the nightly takes this
233	// call as it stands and only bootstrap opts the README row in.
234	export async function convergeWiring(root, fullName, stubText, secretNames = [], { badges = false } = {}) {
235	  const changed = [];
236	  if (convergeSchedulerWorkflow(root, fullName, stubText, secretNames)) changed.push(SCHEDULER_WORKFLOW);
237	  const hooks = ensureHooks(root);
238	  for (const h of hooks.added) changed.push(`hook:${h}`);
239	  if (removeRetiredCorpusImport(root)) changed.push(`removed retired ${CLAUDE_MD} corpus import`);
240	  if (removeRetiredBadgeSetting(root)) changed.push('removed retired badges setting');
241	  if (badges && convergeBadgeRow(root, await badgeRowEntries(root, await repoConfig(root)))) changed.push(`${README} pack row`);
242	  return { changed, ...(hooks.error ? { error: hooks.error } : {}) };
243	}
244	
245	// CLI: `node converge-wiring.mjs [owner/repo] [--badges]` — converge THIS repo's
246	// wiring. The full name comes from argv or GITHUB_REPOSITORY/CLAUDINITE_REPO; the
247	// scheduler stub from the vendored mount. This is the single surface bootstrap
248	// (Part 6) and baselining both invoke, so the wiring set is defined once, here —
249	// with `--badges` the one thing that differs between them: bootstrap passes it to
250	// seed the README pack row, the nightly leaves the README alone.
251	async function main() {
252	  const argv = process.argv.slice(2);
253	  const badges = argv.includes('--badges');
254	  const fullName = argv.find((a) => !a.startsWith('--')) || process.env.GITHUB_REPOSITORY || process.env.CLAUDINITE_REPO;
255	  if (!fullName) { console.error('converge-wiring: need owner/repo (argv or GITHUB_REPOSITORY)'); process.exit(1); }
256	  const root = process.env.CLAUDINITE_REPO_ROOT || process.cwd();
257	  const stubPath = join(root, '.claudinite/shared/engine/scheduler/stubs/claudinite-scheduler.yml');
258	  if (!existsSync(stubPath)) { console.error(`converge-wiring: vendored stub not found at ${stubPath}`); process.exit(1); }
259	  const secretNames = await declaredSecrets(root, await repoConfig(root));
260	  const { changed, error } = await convergeWiring(root, fullName, readFileSync(stubPath, 'utf8'), secretNames, { badges });
261	  if (error) console.log(`! ${error}`);
262	  console.log(changed.length ? `converge-wiring: ${changed.join(', ')}` : 'converge-wiring: already converged');
263	}
264	
265	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) main();
266

